<template>
  <main class="portal-main">
    <section class="portal-hero"><span>CHENGDU UNIVERSITY LIBRARY NETWORK</span><h1>一本书，连接整座城市的校园</h1><p>检索四所高校、九个校区的共享馆藏</p>
      <div class="search-box"><el-input v-model="keyword" size="large" placeholder="输入书名、作者、ISBN 或关键词" clearable @keyup.enter="search"/><el-select v-model="categoryId" clearable placeholder="全部类别"><el-option v-for="c in categories" :key="Number(c.category_id)" :label="String(c.category_name)" :value="Number(c.category_id)"/></el-select><el-select v-model="libraryId" clearable filterable placeholder="全部图书馆"><el-option v-for="l in libraries" :key="Number(l.library_id)" :label="String(l.library_name)+'（Site '+l.site_id+'）'" :value="Number(l.library_id)"/></el-select><el-button type="primary" size="large" :loading="loading" @click="search">搜索图书</el-button></div>
    </section>
    <section class="book-section"><div class="section-head"><div><h2>{{ keyword ? '“'+keyword+'”的搜索结果' : '全网推荐书目' }}</h2><p>点击书目可查看馆藏高校、校区、可借状态和具体图书馆</p></div><span>{{ books.length }} RESULTS</span></div>
      <div class="book-grid"><article v-for="book in books" :key="Number(book.book_id)" class="book-card" tabindex="0" @click="openDetail(book)" @keyup.enter="openDetail(book)"><div class="book-cover">{{ String(book.title).slice(0,1) }}</div><div class="book-info"><span>{{ book.category_name }}</span><h3>{{ book.title }}</h3><p>{{ book.author || '作者未知' }} · {{ book.publisher }}</p><small>{{ book.summary }}</small><footer><b>ISBN {{ book.isbn || '—' }}</b><button>查看详情与馆藏 →</button></footer></div></article></div>
      <el-empty v-if="!loading&&!books.length" description="没有找到匹配书目"/>
    </section>
    <el-dialog v-model="detailVisible" width="min(820px, 92vw)" class="book-dialog" destroy-on-close>
      <template #header><div class="detail-title"><span>{{ detail?.book.category_name }}</span><h2>{{ detail?.book.title }}</h2><p>{{ detail?.book.author }} · {{ detail?.book.publisher }} · {{ detail?.book.publish_year }}</p></div></template>
      <div v-loading="detailLoading" class="detail-body">
        <template v-if="detail"><div class="detail-stats"><div><strong>{{ detail.schools.length }}</strong><span>所高校收藏</span></div><div><strong>{{ detail.copy_count }}</strong><span>馆藏副本</span></div><div><strong>{{ detail.available_count }}</strong><span>当前可借</span></div></div>
        <dl><dt>ISBN</dt><dd>{{ detail.book.isbn||'—' }}</dd><dt>分类</dt><dd>{{ detail.book.category_name }}</dd><dt>版本/语言</dt><dd>{{ detail.book.edition||'—' }} / {{ detail.book.language||'—' }}</dd><dt>页数</dt><dd>{{ detail.book.page_count||'—' }}</dd><dt>内容简介</dt><dd class="summary">{{ detail.book.summary||'暂无简介' }}</dd></dl>
        <h3>馆藏分布</h3><div class="holdings"><article v-for="copy in detail.copies" :key="Number(copy.copy_id)"><div><strong>{{ copy.university_name }}</strong><span>{{ copy.campus_name }} · {{ copy.library_name }}</span><small>{{ copy.address }}</small></div><div class="copy-state"><b :class="{available:copy.copy_status==='AVAILABLE'}">{{ copy.copy_status }}</b><span>Site {{ copy.site_id }} · {{ copy.shelf_location||'未设置架位' }}</span></div></article><el-empty v-if="!detail.copies.length" description="暂无实体馆藏"/></div></template>
      </div>
    </el-dialog>
  </main>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { apiErrorMessage,getBookDetail,getCatalogOptions,searchPublicBooks } from '@/api/client';import { ElMessage } from 'element-plus';import type { DataRow } from '@/types'
const keyword=ref(''),categoryId=ref<number>(),libraryId=ref<number>(),books=ref<DataRow[]>([]),categories=ref<DataRow[]>([]),libraries=ref<DataRow[]>([]),loading=ref(false),detailLoading=ref(false),detailVisible=ref(false),detail=ref<Awaited<ReturnType<typeof getBookDetail>>>()
async function search(){loading.value=true;try{books.value=(await searchPublicBooks(keyword.value,categoryId.value,libraryId.value)).rows}catch(e){ElMessage.error(apiErrorMessage(e))}finally{loading.value=false}}
async function openDetail(book:DataRow){detailVisible.value=true;detailLoading.value=true;detail.value=undefined;try{detail.value=await getBookDetail(Number(book.book_id))}catch(e){ElMessage.error(apiErrorMessage(e))}finally{detailLoading.value=false}}
onMounted(async()=>{try{const options=await getCatalogOptions();categories.value=options.categories;libraries.value=options.libraries}catch(e){ElMessage.error(apiErrorMessage(e))}await search()})
</script>
