ce-between;margin-top:10px}.book-info b{color:#9aabad;font:8px 'DM Mono'}.book-info button{border:0;background:none;color:#087f76;font-size:9px;cursor:pointer}.detail-title span{color:#078b80;font-size:9px}.detail-title h2{margin:5px 0;color:#18374a}.detail-title p{margin:0;color:#7e9299;font-size:10px}.detail-body{min-height:180px;color:#234252}.detail-stats{display:grid;grid-template-columns:repeat(3,1fr);background:#f2f8f7;border-radius:8px;margin-bottom:18px}.detail-stats div{text-align:center;padding:15px;border-right:1px solid #dbe9e7}.detail-stats div:last-child{border:0}.detail-stats strong{display:block;color:#078b80;font:500 21px 'DM Mono'}.detail-stats span{font-size:9px;color:#7e9299}.detail-body dl{display:grid;grid-template-columns:90px 1fr 90px 1fr;font-size:10px}.detail-body dt{color:#84979d;padding:6px}.detail-body dd{margin:0;padding:6px}.detail-body .summary{grid-column:2/-1;line-height:1.7}.detail-body h3{font-size:13px;margin-top:20px}.holdings{border:1px solid #e2ebec;border-radius:8px;overflow:hidden}.holdings article{display:flex;justify-content:space-between;gap:16px;padding:13px 15px;border-bottom:1px solid #ebf1f2}.holdings article:last-child{border:0}.holdings article>div{display:flex;flex-direction:column}.holdings strong{font-size:11px}.holdings span,.holdings small{font-size:9px;color:#7b9097;margin-top:3px}.copy-state{text-align:right}.copy-state b{color:#d77c36;font:9px 'DM Mono'}.copy-state b.available{color:#078b80}@media(max-width:850px){.search-box{grid-template-columns:1fr 1fr}.book-grid{grid-template-columns:1fr}}@media(max-width:520px){.search-box{grid-template-columns:1fr}.portal-hero h1{font-size:23px}.detail-body dl{grid-template-columns:75px 1fr}.detail-body .summary{grid-column:2}.holdings article{flex-direction:column}.copy-state{text-align:left}}
